export const REWARD_INTERVAL_MS=600000,REWARD_XP=10;
export function defaultRewards(){return{version:1,entries:{}}}
export function rewardTotals(ledger){const movingMs=Object.values(ledger?.entries||{}).reduce((sum,e)=>sum+e.creditedMs,0),xp=Math.floor(movingMs/REWARD_INTERVAL_MS)*REWARD_XP;return{movingMs,xp,remainingMs:REWARD_INTERVAL_MS-movingMs%REWARD_INTERVAL_MS}}
export function validateRewards(raw,sites,now=Date.now()){if(!raw||raw.version!==1||!raw.entries||typeof raw.entries!=='object'||Array.isArray(raw.entries)||Object.keys(raw.entries).length>10000)throw Error('Invalid reward ledger');const entries={};for(const [id,e]of Object.entries(raw.entries)){if(!e||!sites.some(s=>s.id===e.fromId)||!sites.some(s=>s.id===e.toId)||!Number.isSafeInteger(e.startedAt)||e.startedAt<1||e.startedAt>now+60000||id!==`${e.fromId}:${e.toId}:${e.startedAt}`||!Number.isSafeInteger(e.maxMs)||e.maxMs<1||e.maxMs>28800000||!Number.isSafeInteger(e.creditedMs)||e.creditedMs<0||e.creditedMs>e.maxMs)throw Error('Invalid reward entry');entries[id]={fromId:e.fromId,toId:e.toId,startedAt:e.startedAt,maxMs:e.maxMs,creditedMs:e.creditedMs}}return{version:1,entries}}
export function creditRewards(ledger,j,now=Date.now()){if(!j)return ledger;const gameMs=Math.ceil(j.route.durationSeconds/3*1000),waitMs=j.route.mode==='bus'?40000:0,maxMs=gameMs-waitMs;if(maxMs<1)return ledger;const elapsed=Math.min(gameMs,Math.max(0,(j.pausedAt??now)-j.startedAt-j.pausedMs)),creditedMs=Math.floor(Math.max(0,elapsed-waitMs)),id=`${j.fromId}:${j.toId}:${j.startedAt}`,old=ledger.entries[id];if(old&&old.maxMs!==maxMs)throw Error('Conflicting journey reward');if(old&&old.creditedMs>=creditedMs)return ledger;return{version:1,entries:{...ledger.entries,[id]:{fromId:j.fromId,toId:j.toId,startedAt:j.startedAt,maxMs,creditedMs}}}}
export function mergeRewards(a,b,sites){a=validateRewards(a,sites);b=validateRewards(b,sites);const entries={...a.entries};for(const [id,e]of Object.entries(b.entries)){const old=entries[id];if(old&&old.maxMs!==e.maxMs)throw Error('Conflicting reward entry');if(!old||e.creditedMs>old.creditedMs)entries[id]=e}return{version:1,entries}}
